item.content:encoded:
@font-face {
  font-family: "ClashDisplay-Bold";
  src:  url("https://doghousemedia.ie/wp-content/themes/dhm-theme/fonts/ClashDisplay-Medium.woff2") format("woff2"), url("https://doghousemedia.ie/wp-content/themes/dhm-theme/fonts/ClashDisplay-Medium.woff") format("woff");  font-weight: normal;
  font-style: normal;

}

@font-face {
  font-family: 'ClashDisplay';
  src: url('https://doghousemedia.ie/wp-content/themes/dhm-theme/fonts/ClashDisplay-Regular.woff2') format('woff2'),
       url('https://doghousemedia.ie/wp-content/themes/dhm-theme/fonts/ClashDisplay-Regular.woff') format('woff');
  font-weight: 400;
}

@font-face {
  font-family: 'ClashDisplay';
  src: url('https://doghousemedia.ie/wp-content/themes/dhm-theme/fonts/ClashDisplay-Medium.woff2') format('woff2'),
       url('https://doghousemedia.ie/wp-content/themes/dhm-theme/fonts/ClashDisplay-Medium.woff') format('woff');
  font-weight: 500;
}

/* Fix: Prevent off-canvas container from clipping fixed-position chat widget */
.pp-offcanvas-container {
    overflow: visible !important;
}


body {font-family: ClashDisplay;}

h1, h2, h3, h4, h5, h6 {font-family: ClashDisplay; font-weight:500;}

.hero-h1 h1 {font-size:78px;}

.larger{font-size:26px; line-height:1.7}

.single .fl-post-header,
.blog .fl-post-header,
.category .fl-post-header {
  display: block;
}

 .vertical-line{
        border-left: 2px solid #cccccc;
            height: 200px;
            position:absolute;
            left: 50%;
            z-index: 100;

    }



.divider-vertical {
    position: absolute;
    left: 0%;
    right: 0%;
	top:0;
    z-index: 1;
    height: 200px;
    max-width: 2px;
    margin: 0 auto;
    background-color: #cecece;
}

@media screen and (max-width: 1023px) and (min-width:768px) {
	.hero-h1 h1 {font-size: 48px;}
		.larger{font-size:23px;}

}

@media screen and (max-width: 767px) {
  .hero-h1 h1 {font-size: 38px;}
	.vertical-line  {height: 100px;}
	.fl-post-feed-post.fl-post-feed-image-beside, .fl-post-feed-post.fl-post-feed-image-beside-right {max-width:100%;}
	.larger{font-size:20px;}
	}

